#import "PVXHLSManifest.h"
#include <math.h>

static NSString *PVXHLSResolve(NSURL *base,NSString *raw){if(![raw isKindOfClass:NSString.class]||!raw.length)return nil;NSURL *u=[NSURL URLWithString:raw relativeToURL:base].absoluteURL;NSString *scheme=u.scheme.lowercaseString;return u&&([scheme isEqual:@"http"]||[scheme isEqual:@"https"]||[scheme isEqual:@"file"])?u.absoluteString:nil;}
static NSDictionary *PVXHLSAttrs(NSString *text,NSError **error){NSMutableDictionary *out=[NSMutableDictionary dictionary];NSUInteger i=0,start=0;BOOL quote=NO;while(i<=text.length){unichar c=i<text.length?[text characterAtIndex:i]:',';if(c=='"')quote=!quote;if((c==','&&!quote)||i==text.length){NSString *part=[text substringWithRange:NSMakeRange(start,i-start)];NSRange eq=[part rangeOfString:@"="];if(eq.location==NSNotFound){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:2 userInfo:@{NSLocalizedDescriptionKey:@"HLS 属性缺少等号"}];return nil;}NSString *key=[[part substringToIndex:eq.location] stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];NSString *value=[[part substringFromIndex:eq.location+1] stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(!key.length||out[key]){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:3 userInfo:@{NSLocalizedDescriptionKey:@"HLS 属性重复或为空"}];return nil;}if(value.length>=2&&[value hasPrefix:@"\""]&&[value hasSuffix:@"\""])value=[value substringWithRange:NSMakeRange(1,value.length-2)];out[key]=value;start=i+1;}i++;}if(quote&&error)*error=[NSError errorWithDomain:@"PVXHLS" code:4 userInfo:@{NSLocalizedDescriptionKey:@"HLS 属性引号未闭合"}];return quote?nil:out;}
static NSInteger PVXInt(NSString *s){return (NSInteger)s.longLongValue;}
static long long PVXLong(NSString *s){return s.longLongValue;}
static BOOL PVXBool(NSString *s){return [s.uppercaseString isEqual:@"YES"]||[s isEqual:@"1"]||[s.uppercaseString isEqual:@"TRUE"];}
@implementation PVXHLSKey @end
@implementation PVXHLSMap @end
@implementation PVXHLSSegment @end
@implementation PVXHLSVariant @end
@implementation PVXHLSEntry @end
@implementation PVXHLSManifest
+ (instancetype)parseData:(NSData *)data baseURL:(NSURL *)baseURL error:(NSError **)error{NSString *text=[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding];if(!text){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:1 userInfo:@{NSLocalizedDescriptionKey:@"HLS 不是 UTF-8 清单"}];return nil;}return [self parseText:text baseURL:baseURL error:error];}
+ (instancetype)parseText:(NSString *)text baseURL:(NSURL *)baseURL error:(NSError **)error{
 if(![text hasPrefix:@"#EXTM3U"]){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:5 userInfo:@{NSLocalizedDescriptionKey:@"HLS 清单缺少 EXTM3U"}];return nil;}
 PVXHLSManifest *m=[self new];m->_baseURL=baseURL;m->_sourceText=[text copy];NSMutableArray *variants=[NSMutableArray array],*audio=[NSMutableArray array],*segments=[NSMutableArray array];NSArray *lines=[text componentsSeparatedByString:@"\n"];NSString *pendingStream=nil,*pendingInf=nil,*pendingRange=nil;PVXHLSKey *key=nil;PVXHLSMap *map=nil;BOOL discontinuity=NO,gap=NO;long long seq=0;BOOL hasStream=NO;
 for(NSString *raw in lines){NSString *line=[raw stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(!line.length)continue;
  if([line hasPrefix:@"#EXT-X-VERSION:"]){m->_version=PVXInt([line substringFromIndex:14]);continue;}
  if([line hasPrefix:@"#EXT-X-MEDIA-SEQUENCE:"]){m->_mediaSequence=PVXLong([line substringFromIndex:22]);seq=m->_mediaSequence;continue;}
  if([line isEqual:@"#EXT-X-ENDLIST"]){m->_endList=YES;continue;}
  if([line hasPrefix:@"#EXT-X-TARGETDURATION:"]){m->_targetDuration=[line substringFromIndex:22].doubleValue;continue;}
  if([line isEqual:@"#EXT-X-DISCONTINUITY"]){discontinuity=YES;continue;}
  if([line isEqual:@"#EXT-X-GAP"]){gap=YES;continue;}
  if([line hasPrefix:@"#EXT-X-KEY:"]){NSError *e=nil;NSDictionary *a=PVXHLSAttrs([line substringFromIndex:11],&e);if(!a){if(error)*error=e;return nil;}NSString *method=a[@"METHOD"];if([method.uppercaseString isEqual:@"SAMPLE-AES"]||[method.uppercaseString isEqual:@"SAMPLE-AES-CTR"]){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:6 userInfo:@{NSLocalizedDescriptionKey:@"不支持 SAMPLE-AES"}];return nil;}PVXHLSKey *k=[PVXHLSKey new];k.method=method?:@"NONE";k.URI=PVXHLSResolve(baseURL,a[@"URI"]);k.IV=a[@"IV"];k.keyformat=a[@"KEYFORMAT"]?:@"identity";if(![k.keyformat.lowercaseString isEqual:@"identity"]&&k.URI.length){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:7 userInfo:@{NSLocalizedDescriptionKey:@"不支持非 identity KEYFORMAT"}];return nil;}key=k;continue;}
  if([line hasPrefix:@"#EXT-X-MAP:"]){NSError *e=nil;NSDictionary *a=PVXHLSAttrs([line substringFromIndex:11],&e);if(!a){if(error)*error=e;return nil;}PVXHLSMap *x=[PVXHLSMap new];x.URI=PVXHLSResolve(baseURL,a[@"URI"]);x.byterange=a[@"BYTERANGE"];if(!x.URI.length){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:8 userInfo:@{NSLocalizedDescriptionKey:@"MAP URI 无效"}];return nil;}map=x;continue;}
  if([line hasPrefix:@"#EXT-X-BYTERANGE:"]){pendingRange=[line substringFromIndex:17];continue;}
  if([line hasPrefix:@"#EXT-X-STREAM-INF:"]){pendingStream=[line substringFromIndex:18];hasStream=YES;continue;}
  if([line hasPrefix:@"#EXT-X-MEDIA:"]){NSError *e=nil;NSDictionary *a=PVXHLSAttrs([line substringFromIndex:13],&e);if(!a){if(error)*error=e;return nil;}if([a[@"TYPE"] isEqual:@"AUDIO"]&&a[@"URI"]){PVXHLSEntry *x=[PVXHLSEntry new];x.URI=PVXHLSResolve(baseURL,a[@"URI"]);x.groupID=a[@"GROUP-ID"];x.name=a[@"NAME"];x.language=a[@"LANGUAGE"];x.isDefault=PVXBool(a[@"DEFAULT"]);x.autoselect=PVXBool(a[@"AUTOSELECT"]);[audio addObject:x];}continue;}
  if([line hasPrefix:@"#EXTINF:"]){pendingInf=[line substringFromIndex:8];continue;}
  if([line hasPrefix:@"#"]){continue;}
  if(pendingStream){NSError *e=nil;NSDictionary *a=PVXHLSAttrs(pendingStream,&e);if(!a){if(error)*error=e;return nil;}PVXHLSVariant *v=[PVXHLSVariant new];v.URI=PVXHLSResolve(baseURL,line);v.bandwidth=PVXLong(a[@"BANDWIDTH"]);v.averageBandwidth=PVXLong(a[@"AVERAGE-BANDWIDTH"]);v.codecs=a[@"CODECS"];v.audioGroup=a[@"AUDIO"];NSString *res=a[@"RESOLUTION"];NSArray *dims=[res componentsSeparatedByString:@"x"];if(dims.count==2){v.width=PVXInt(dims[0]);v.height=PVXInt(dims[1]);}if(!v.URI.length){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:9 userInfo:@{NSLocalizedDescriptionKey:@"变体 URI 无效"}];return nil;}[variants addObject:v];pendingStream=nil;continue;}
  if(pendingInf){PVXHLSSegment *seg=[PVXHLSSegment new];seg.URI=PVXHLSResolve(baseURL,line);NSString *inf=pendingInf;NSRange comma=[inf rangeOfString:@","];seg.duration=(comma.location==NSNotFound?inf:[inf substringToIndex:comma.location]).doubleValue;seg.title=comma.location==NSNotFound?@"": [inf substringFromIndex:comma.location+1];seg.sequence=seq++;seg.byterange=pendingRange;seg.key=key;seg.map=map;seg.discontinuity=discontinuity;seg.gap=gap;if(!seg.URI.length||seg.duration<=0){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:10 userInfo:@{NSLocalizedDescriptionKey:@"分片 URI 或时长无效"}];return nil;}[segments addObject:seg];pendingInf=nil;pendingRange=nil;discontinuity=NO;gap=NO;continue;}
 }
 m->_master=hasStream;m->_variants=[variants copy];m->_audioRenditions=[audio copy];m->_segments=[segments copy];if(!m.master&&!m.endList){if(error)*error=[NSError errorWithDomain:@"PVXHLS" code:11 userInfo:@{NSLocalizedDescriptionKey:@"只支持完整 VOD 清单"}];return nil;}return m;
}
- (PVXHLSVariant *)bestVariant{return [self.variants sortedArrayUsingComparator:^NSComparisonResult(PVXHLSVariant*a,PVXHLSVariant*b){long long aa=(long long)a.width*a.height,bb=(long long)b.width*b.height;if(aa!=bb)return aa>bb?NSOrderedAscending:NSOrderedDescending;long long ab=MAX(a.averageBandwidth,a.bandwidth),bbt=MAX(b.averageBandwidth,b.bandwidth);return ab==bbt?NSOrderedSame:(ab>bbt?NSOrderedAscending:NSOrderedDescending);}].firstObject;}
- (PVXHLSEntry *)defaultAudioForGroup:(NSString *)groupID{for(PVXHLSEntry *x in self.audioRenditions)if([x.groupID isEqual:groupID]&&x.isDefault)return x;for(PVXHLSEntry *x in self.audioRenditions)if([x.groupID isEqual:groupID])return x;return nil;}
- (NSString *)localizedTextWithSegmentURLs:(NSDictionary<NSString *,NSString *> *)localURLs{return [self localizedTextWithSegments:self.segments localURLs:localURLs];}
- (NSString *)localizedTextWithSegments:(NSArray<PVXHLSSegment *> *)segments localURLs:(NSDictionary<NSString *,NSString *> *)localURLs{NSMutableString *out=[NSMutableString stringWithString:@"#EXTM3U\n"];if(self.version>0)[out appendFormat:@"#EXT-X-VERSION:%ld\n",(long)self.version];if(self.targetDuration>0)[out appendFormat:@"#EXT-X-TARGETDURATION:%ld\n",(long)ceil(self.targetDuration)];[out appendFormat:@"#EXT-X-MEDIA-SEQUENCE:%lld\n",self.mediaSequence];for(PVXHLSSegment *seg in segments){if(seg.discontinuity)[out appendString:@"#EXT-X-DISCONTINUITY\n"];if(seg.gap)[out appendString:@"#EXT-X-GAP\n"];if(seg.map.URI.length)[out appendFormat:@"#EXT-X-MAP:URI=\"%@\"%@\n",localURLs[seg.map.URI]?:seg.map.URI,seg.map.byterange.length?[NSString stringWithFormat:@",BYTERANGE=\"%@\"",seg.map.byterange]:@""];if(seg.key.method.length){if([seg.key.method.uppercaseString isEqual:@"NONE"])[out appendString:@"#EXT-X-KEY:METHOD=NONE\n"];else [out appendFormat:@"#EXT-X-KEY:METHOD=%@,URI=\"%@\"%@%@\n",seg.key.method,localURLs[seg.key.URI]?:seg.key.URI,seg.key.IV.length?[NSString stringWithFormat:@",IV=%@",seg.key.IV]:@"",seg.key.keyformat.length?[NSString stringWithFormat:@",KEYFORMAT=\"%@\"",seg.key.keyformat]:@""];}if(seg.byterange.length)[out appendFormat:@"#EXT-X-BYTERANGE:%@\n",seg.byterange];[out appendFormat:@"#EXTINF:%.6f,%@\n%@\n",seg.duration,seg.title?:@"",localURLs[seg.URI]?:seg.URI];}if(self.endList)[out appendString:@"#EXT-X-ENDLIST\n"];return out;}

@end
